using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    List<Course> GetAllCourses();
    List<Course> GetFeaturedCourses();
    List<Course> SearchCourses(string? searchTerm, string? departmentCode);
    Course? GetCourseById(int id);
}

public class CatalogService : ICatalogService
{
    private readonly List<Course> _courses;
    private readonly List<Department> _departments;

    public CatalogService()
    {
        _courses = BuildSeedData();
        _departments = _courses
            .GroupBy(c => new { c.DepartmentCode, c.DepartmentName })
            .Select(g => new Department
            {
                Code = g.Key.DepartmentCode,
                Name = g.Key.DepartmentName,
                CourseCount = g.Count()
            })
            .OrderBy(d => d.Name)
            .ToList();
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
            query = query.Where(c => c.DepartmentCode == departmentCode);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.DepartmentCode).ThenBy(c => c.CourseCode).ToList();
    }

    public Course? GetCourseById(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    private static List<Course> BuildSeedData() =>
    [
        new()
        {
            Id = 1, CourseCode = "CS101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of major CS subfields. No prior experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201",
            DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true,
            Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Dr. Lovelace has 15 years of experience teaching introductory CS. Her research focuses on CS education and accessible computing.", Email = "alovelace@university.edu", OfficeHours = "Tue/Thu 2:00–4:00 PM" }
        },
        new()
        {
            Id = 2, CourseCode = "CS301", Title = "Data Structures & Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes rigorous complexity analysis.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305",
            DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true,
            Instructor = new() { Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Dr. Turing specializes in algorithm design and computational complexity theory. He has published over 40 papers in top-tier conferences.", Email = "aturing@university.edu", OfficeHours = "Mon/Wed 1:00–3:00 PM" }
        },
        new()
        {
            Id = 3, CourseCode = "CS450", Title = "Machine Learning",
            Description = "Foundations of machine learning including supervised and unsupervised learning, neural networks, support vector machines, and ensemble methods. Students complete a capstone project applying ML to a real-world dataset.",
            Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Science Hall 410",
            DepartmentCode = "CS", DepartmentName = "Computer Science",
            Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Bio = "Dr. Hopper is a leading researcher in applied machine learning with a focus on natural language processing and healthcare AI.", Email = "ghopper@university.edu", OfficeHours = "Fri 10:00 AM–12:00 PM" }
        },
        new()
        {
            Id = 4, CourseCode = "MATH201", Title = "Calculus II",
            Description = "Continuation of Calculus I covering techniques of integration, applications of integrals, sequences, series, and an introduction to differential equations.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 102",
            DepartmentCode = "MATH", DepartmentName = "Mathematics",
            Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Dr. Noether is an award-winning mathematics educator whose research bridges abstract algebra and applied calculus.", Email = "enoether@university.edu", OfficeHours = "Tue/Thu 3:00–5:00 PM" }
        },
        new()
        {
            Id = 5, CourseCode = "MATH310", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Emphasizes both theory and computational methods with applications to data science and engineering.",
