public class CatalogService : ICatalogService
{
    private readonly List<Course> _courses;
    private readonly List<Department> _departments;

    public CatalogService()
    {
        _courses = BuildSeedData();
        _departments = _courses
            .GroupBy(c => new { c.DepartmentCode, c.DepartmentName })
            .Select(g => new Department
            {
                Code = g.Key.DepartmentCode,
                Name = g.Key.DepartmentName,
                CourseCount = g.Count()
            })
            .OrderBy(d => d.Name)
            .ToList();
    }

    public List<Department> GetDepartments() => _departments;

