{"file_text": "<div class="card border-0 bg-light">
    <div class="card-body">
        <h5 class="card-title">@Instructor.Name</h5>
        <p class="text-muted mb-2">@Instructor.Title</p>
        <p>@Instructor.Bio</p>
        <ul class="list-unstyled mb-0">
            <li><strong>Email:</strong> <a href="mailto:@Instructor.Email">@Instructor.Email</a></li>
            <li><strong>Office Hours:</strong> @Instructor.OfficeHours</li>
        </ul>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Instructor Instructor { get; set; } = default!;
}
", "path": "/tmp/sv-932276b4b38f4ba790bb55a7306d1221/UniversityCourseCatalog/Components/Shared/InstructorBio.razor"}

{"file_text": "<div class="row g-3 mb-4">
    <div class="col-md-8">
        <input type="text" class="form-control" placeholder="Search by course title, code, or instructor…"
               value="@SearchTerm" @oninput="OnSearchInput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" value="@SelectedDepartment" @onchange="OnDepartmentChange">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Code">@dept.Name (@dept.CourseCount)</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public string SelectedDepartment { get; set; } = string.Empty;
    [Parameter] public List<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<string> OnSearchTermChanged { get; set; }
    [Parameter] public EventCallback<string> OnSelectedDepartmentChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        await OnSearchTermChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        await OnSelectedDepartmentChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}
