    private string _selectedDepartment = string.Empty;

    [SupplyParameterFromQuery(Name = "department")]
    public string? InitialDepartment { get; set; }

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _selectedDepartment = InitialDepartment ?? string.Empty;
        ApplyFilters();
    }

    private void HandleSearchChanged(string term)
    {
        _searchTerm = term;
        ApplyFilters();
    }

    private void HandleDepartmentChanged(string dept)
    {
        _selectedDepartment = dept;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        _filteredCourses = Catalog.SearchCourses(_searchTerm, _selectedDepartment);
    }
}

