@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enroll – University Course Catalog</PageTitle>

<div class="container-fluid px-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@_selectedCourseTitle</strong> has been received. You will be notified by email once it is processed.</p>
            <a href="courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-lg-6">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" class="form-control" @bind-Value="_model.FullName" />
                        <ValidationMessage For="() => _model.FullName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId"
                                   placeholder="e.g., CS123456" />
                        <ValidationMessage For="() => _model.StudentId" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id">@course.CourseCode – @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                </EditForm>
            </div>
            <div class="col-lg-6 mt-4 mt-lg-0">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">How Enrollment Works</h5>
                        <ol>
                            <li>Fill out the form with your name and student ID.</li>
                            <li>Select the course you want to enroll in.</li>
                            <li>Submit the form — you'll receive a confirmation email.</li>
                            <li>The registrar will process your request within 2 business days.</li>
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    protected override void OnInitialized()
    {
        _courses = Catalog.GetAllCourses();
        if (PreselectedCourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourseById(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.CourseCode} – {course.Title}" : "Unknown";
        _submitted = true;
    }
}

