@page "/courses"
@rendermode InteractiveServer
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Courses – University Course Catalog</PageTitle>

<div class="container-fluid px-4">
    <h1 class="mb-4">Course Catalog</h1>

    <CourseFilters SearchTerm="@_searchTerm"
                   SelectedDepartment="@_selectedDepartment"
                   Departments="_departments"
                   OnSearchTermChanged="HandleSearchChanged"
                   OnSelectedDepartmentChanged="HandleDepartmentChanged" />

    @if (_filteredCourses.Count == 0)
    {
        <div class="alert alert-info">
            No courses match your search. Try adjusting your filters.
        </div>
    }
    else
    {
        <p class="text-muted mb-3">Showing @_filteredCourses.Count course(s)</p>
        <div class="row g-4">
            @foreach (var course in _filteredCourses)
