<PageTitle>University Course Catalog</PageTitle>

<div class="container-fluid px-4">
    <div class="py-5 text-center">
        <h1 class="display-5 fw-bold">University Course Catalog</h1>
        <p class="lead text-muted">Explore our departments, browse courses, and enroll for the upcoming semester.</p>
        <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
        <a href="enroll" class="btn btn-outline-success btn-lg">Enroll Now</a>
    </div>

    <section class="mb-5">
        <h2 class="mb-3">Departments</h2>
        <div class="row g-3">
            @foreach (var dept in _departments)
            {
                <div class="col-6 col-md-4 col-lg-2">
                    <a href="courses?department=@dept.Code" class="text-decoration-none">
                        <div class="card text-center h-100 border-primary">
                            <div class="card-body">
                                <h6 class="card-title mb-1">@dept.Name</h6>
                                <span class="text-muted small">@dept.CourseCount courses</span>
                            </div>
                        </div>
                    </a>
                </div>
            }
        </div>
    </section>

    <section class="mb-5">
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row g-4">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-6 col-lg-4">
                    <CourseCard Course="course" />
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<Department> _departments = [];
    private List<Course> _featuredCourses = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _featuredCourses = Catalog.GetFeaturedCourses();
    }
}

